# -*- coding: utf-8 -*-
"""Plot idvd.csv generated by mosfet.py idvd."""

import pandas as pd
import plotly.express as px

df = pd.read_csv("idvd.csv")

fig = px.line(
    df,
    x="Vd_V",
    y="Id_A_per_um",
    markers=True,
    title="DEVSIM Id–Vd Characteristics (Vg = 2.0 V)",
    labels={
        "Vd_V": "Vd (V)",
        "Id_A_per_um": "Id (A/µm)",
    },
)
fig.update_layout(height=500, margin=dict(l=50, r=30, t=60, b=50))
fig.show()
